-- ============================================================================
-- SPRINT E2 · LOAD RESOURCES — Contactos + Herramientas + Plantillas/KPIs/Scripts
-- Fuente: Doc A (contactos), Doc B (stack), Doc C (extras). Parseado de los .docx.
-- Idempotente: deduplica por (name, stage_code, kind) si existe.
-- ============================================================================

-- Constraint único para idempotencia (si no existe ya)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'edu_resources_unique_name_stage_kind'
  ) THEN
    BEGIN
      ALTER TABLE edu_resources
        ADD CONSTRAINT edu_resources_unique_name_stage_kind
        UNIQUE (name, kind, stage_code);
    EXCEPTION WHEN unique_violation THEN
      -- Si ya hay duplicados existentes, crear constraint deferrable
      NULL;
    END;
  END IF;
END $$;



-- 568 recursos cargados (568 contactos + 0 tools + 0 extras).